@page "/dashboard"
@using sv_2b81730be038430685ee6fd48fd856ba.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="lead">Currently viewing: <strong>@WarehouseState.SelectedWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text display-4">
                    @if (_isPolling)
                    {
                        <span class="@(_alertCount > 5 ? "text-danger" : "text-warning")">@_alertCount</span>
                    }
                    else
                    {
                        <span class="text-muted">--</span>
                    }
                </p>
                <p class="text-muted small">
                    @if (_isPolling)
                    {
                        <text>Refreshes every 10 seconds</text>
                    }
                    else
                    {
                        <text>Starting...</text>
                    }
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Warehouse ID</h5>
                <p class="card-text"><code>@WarehouseState.SelectedWarehouseId</code></p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Active</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Inactive</span>
                    }
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _alertCount;
    private bool _isPolling;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(OnAlertUpdated);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        StopPolling();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        _alertCount = AlertService.CurrentLowStockCount;
        await InvokeAsync(StateHasChanged);

        // Start background polling loop
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(cancellationToken))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
                _alertCount = AlertService.CurrentLowStockCount;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when disposed or warehouse changes
        }
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        await StartPollingAsync();
    }

    private void OnAlertUpdated()
    {
        _alertCount = AlertService.CurrentLowStockCount;
        StateHasChanged();
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
        _isPolling = false;
    }

    public void Dispose()
    {
        StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

